param([ValidateSet('filter','real')][string]$Kind='filter',[ValidateSet('build','test')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-projection-interval-filter-20260914';$seed='D:\projects\AIMA-public-projection-interval-20260914'
$sha='be477fa38e72a521629845246be41df690bf3205';$bundle='D:\projects\projection-interval-filter-be477fa.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '58ad5bfe0c10c6a5c4bd96b929faa743378e86f704ee9fa5b469c10dabb7de11'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo ('build\'+$Kind);$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\projection_interval_filter_selftest.cpp'
if($Kind -eq 'real'){$source=Join-Path $repo 'tests\native\projection_safety_selftest.cpp'}
$exe=Join-Path $build $(if($Kind -eq 'real'){'qrt-projection-safety.exe'}else{'projection-interval-filter-'+$Kind+'.exe'})
$provenance=Join-Path $build 'build-provenance.json'
$sourceInputs=@();$sourceFiles=@($source,(Join-Path $repo 'native\providers\sm121_attention_capacity.h'))
foreach($dir in @('native\providers\moe_accumulator','native\providers\gdn','native\providers\ck_fmha','tests\native')){
 $sourceFiles+=@(Get-ChildItem (Join-Path $repo $dir) -Filter '*.h' -File|ForEach-Object {$_.FullName})
}
if($Kind -eq 'real'){$sourceFiles+=@((Join-Path $repo 'native\providers\whole_provider.cpp'),(Join-Path $repo 'scripts\baiying_build_whole_provider.ps1'))}
foreach($file in $sourceFiles){$sourceInputs+=@{file=$file;sha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; independent original K16 projection controls';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;product_dispatch_changed=$false;purpose='Filter only original selected projection identities with directed WMMA intervals; compact all remaining identities for unchanged four-lane exact replay. Compare complete GB10 BF16 output and raw replayed values by cell. Include preparation,filter,compaction,count read and replay in same-run component clocks.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Kind -eq 'real'){
 $env:QRT_QWEN36_PREFILL_HIPBLASLT_PRODUCER='1';$env:QRT_QWEN36_HAWKEYE_DEVICE_REPLAY='0';$env:QRT_QWEN36_HAWKEYE_PREPARED_OPERANDS='1';$env:QRT_QWEN36_HAWKEYE_ABSOLUTE_PRODUCT_BOUND='0';$env:QRT_QWEN36_HAWKEYE_PREPARED_K16_MAJOR='0';$env:QRT_QWEN36_HAWKEYE_FLOAT_REPLAY='0';$env:QRT_QWEN36_HAWKEYE_ABSOLUTE_PRODUCT_AUDIT='0';$env:QRT_QWEN36_HAWKEYE_ABSOLUTE_PRODUCT_HIPBLASLT='1';$env:QRT_QWEN36_HAWKEYE_PACKED_CANDIDATES='0';$env:QRT_QWEN36_HAWKEYE_CORRECTION_MAXIMUM_BLOCKS_PER_LAUNCH='4096';$env:QRT_PROJECTION_SAFETY_RANGE_REPLAY='0';$env:QRT_PROJECTION_SAFETY_PARTITION_REPLAY='0';$env:QRT_PROJECTION_SAFETY_INTERVAL_REPLAY='1'
}
if($Action -eq 'build'){
 if($Kind -eq 'real'){
  $spec.executable='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
  $spec.arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_whole_provider.ps1'),'-OutDir',$build,'-DppReduction','1','-CompactNormalize','1','-HawkeyeReplayLanes','4','-CompileTimeoutSeconds','180','-ProjectionSafetyTest');$timeout=210
 }else{
  $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
  $spec.arguments=@('-std=c++17','-O3','-Rpass-analysis=kernel-resource-usage','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','-DQRT_CK_SM121_INTERPOLATED_EXP2=1','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=120
 }
}else{
 $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
 $expectedExe=if($Kind -eq 'real'){@($meta.artifacts|Where-Object {$_.name -eq 'qrt-projection-safety.exe'})[0].sha256}else{$meta.executable.sha256}
 if($meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $expectedExe){throw 'Executable provenance mismatch'}
 $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant();$spec.executable=$exe;$spec.arguments=@();$timeout=120
 if($Kind -eq 'real'){
  $inputTensor='D:\projects\AIMA-public-exact-ab-20260910\build\fla-model-q7169-embeddingnorm-capture-r1\input-rmsnorm-bf16.bin';$weightTensor='D:\projects\AIMA-public-capture-20260910\build\layer0-weights-r1\qkv.bin';$referenceTensor='D:\projects\sm121-qkv-reference-9510d980.bin'
  $tensors=@(@{path=$inputTensor;sha256='6c67321f81040780088a742070c48ab3023043b8ef9de71d1ed5a970a8fe9161'},@{path=$weightTensor;sha256='b06edcc9973be74f862d072f89a195e2eecea067ee615144be8510656122401f'},@{path=$referenceTensor;sha256='9510d98057e047e7dd6f4e7b9b6010862e54e938d37bb854078c2de419f0bf37'})
  foreach($tensor in $tensors){if((Get-FileHash $tensor.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $tensor.sha256){throw 'Original QKV tensor changed'}}
  $spec.arguments=@('--real-qkv',$inputTensor,$weightTensor,$referenceTensor,'1000');$spec.tensor_inputs=$tensors
  $spec.model='D:\models\Qwen3.6-35B-A3B; original captured layer-zero QKV';$spec.model_index_sha256='41b9356101ebf8e7519e150dc811f80c4226e727301fbb032b890f006ed0be83';$spec.gb10_reference_host='aitopatom-66c4';$spec.gb10_capture_sha256='5522ec3e4725adf459e505dff61aa3981a08b416b7b2bfe40e929ccf250b4d8b';$spec.prompt_sha256='26515be92b5563d921bade3ed6673ffe9e0c6560fbd7d78f587a0400da802804';$spec.reference_is_compute_input=$false;$spec.selector_error_bound_ppb=1000
 }
}
$out=Join-Path $repo ('build\projection-interval-filter-'+$Kind+'-'+$Action+'-r1');$specPath=Join-Path $build ($Action+'-spec-r1.json')
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Evidence already exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 8|ForEach-Object {$_.Substring(0,[Math]::Min(1200,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native component action failed'}
if($Action -eq 'build'){
 if($Kind -ne 'real'){
  $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
  [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
 }
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 if($Kind -eq 'real'){$reports=@($reports|Where-Object {$_.type -eq 'interval_projection_real_replay'})}
 $expected=if($Kind -eq 'filter'){37}else{2}
 if($reports.Count -ne $expected){throw 'Incomplete interval filter cases'}
 foreach($report in $reports){
  if(-not $report.redzones_pass -or -not $report.immutable_inputs){throw 'Memory failure'}
  if($Kind -eq 'filter' -and ($report.false_admissions -ne 0 -or -not $report.candidate_identity_pass -or -not $report.host_capacity_guards_pass -or -not $report.device_index_guards_pass)){throw 'Filter or identity failure'}
  if($Kind -eq 'real' -and ($report.raw_bit_mismatches -ne 0 -or $report.unrounded_replayed_bit_mismatches -ne 0 -or $report.bf16_mismatches -ne 0 -or $report.elements -ne 58728448 -or $report.initial_candidates -ne 3791742 -or -not $report.same_initial_candidate_identities -or -not $report.candidate_partition_pass)){throw 'Original QKV mismatch'}
 }
}
